const languageFor=path=>{const extension=path?.split('.').pop()?.toLowerCase();return ({js:'javascript',jsx:'javascript',ts:'typescript',tsx:'typescript',py:'python',html:'html',css:'css',scss:'css',json:'json',md:'markdown',yml:'yaml',yaml:'yaml',toml:'toml',sh:'shell',ps1:'powershell'})[extension]||extension||'text'};
const extensionFor=path=>path?.split('.').pop()?.toLowerCase()||'';
const previewKindForPath=path=>['avif','bmp','gif','ico','jpeg','jpg','png','svg','webp'].includes(extensionFor(path))?'image':extensionFor(path)==='pdf'?'pdf':['docx','docm','dotx'].includes(extensionFor(path))?'word':'';
const syntaxPattern=/(\/\/.*|#.*|<!--[\s\S]*?-->|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:async|await|break|case|catch|class|const|continue|def|delete|do|elif|else|except|export|extends|false|finally|for|from|function|if|import|in|interface|let|new|null|pass|raise|return|switch|throw|true|try|type|undefined|var|while|with|yield)\b|\b\d+(?:\.\d+)?\b|[{}()[\].,;:+*\/%=<>!?&|~-]+)/g;
