  useEffect(()=>{if(!task||['passed','failed','blocked','stopped'].includes(task.status)||typeof EventSource==='undefined')return;const events=new EventSource(`${API}/api/tasks/${task.id}/events`);events.onmessage=e=>{const next=JSON.parse(e.data);rememberTask(next);if(['passed','failed','blocked','stopped'].includes(next.status))events.close()};events.onerror=()=>events.close();return()=>events.close()},[task?.id,task?.status]);
  useEffect(()=>{let cancelled=false;async function refreshTasks(){try{const r=await fetch(`${API}/api/tasks`);if(!r.ok)return;const items=await r.json();if(cancelled)return;setSessions(items);setTask(current=>{if(!current)return current;return items.find(item=>item.id===current.id)||current})}catch{}}const timer=setInterval(refreshTasks,1400);return()=>{cancelled=true;clearInterval(timer)}},[]);
  useEffect(()=>{const panel=outputRef.current;if(panel&&task&&['queued','running'].includes(task.status))panel.scrollTop=panel.scrollHeight},[task?.live_output,task?.live_response]);
  useEffect(()=>{document.querySelectorAll('.chat-history').forEach(history=>history.scrollTo({top:history.scrollHeight,behavior:'smooth'}))},[task?.id,task?.messages?.length,task?.live_response,task?.status]);
  useEffect(()=>{if(task)setTodoTarget({session_id:task.id,project_path:task.project_path,branch:task.branch})},[task?.id]);
  useEffect(()=>{const previous=notificationTaskRef.current,terminal=['passed','failed','blocked','stopped'].includes(task?.status),sameTask=!!task&&previous?.id===task.id,newRun=sameTask&&['passed','failed','blocked','stopped'].includes(previous.status)&&!terminal,replyNotified=newRun?false:previous?.replyNotified,newMessages=task?.messages?.slice(sameTask?previous.messageCount:task?.messages?.length)||[],reply=[...newMessages].reverse().find(message=>message.role==='assistant'),finishedWithoutReply=sameTask&&!['passed','failed','blocked','stopped'].includes(previous.status)&&terminal&&!replyNotified,agent=agentLabelFor(task?.agent_type);if(windowsNotifications&&typeof Notification!=='undefined'&&Notification.permission==='granted'&&(reply||finishedWithoutReply)){const summary=(reply?.content||task.summary||task.error||task.step||`پاسخ ${agent} آماده است`).replace(/\s+/g,' ').trim();new Notification(reply?`پاسخ ${agent} آماده است`:`اجرای ${agent} تمام شد`,{body:summary.slice(0,260),tag:`taskloom-${task.id}`})}notificationTaskRef.current=task?{id:task.id,status:task.status,messageCount:task.messages.length,replyNotified:replyNotified||!!reply}:null},[task?.id,task?.status,task?.summary,task?.error,task?.messages?.length,task?.agent_type,windowsNotifications]);
  async function start(e){e.preventDefault();setBusy(true);setNotice('');try{const task_id=taskIdForBranch(form.task_id)||`session-${Date.now().toString(36)}`,session_name=form.session_name.trim()||task_id;const body={...form,task_id,session_name,guide_paths:form.guide_paths.split('\n').map(x=>x.trim()).filter(Boolean),test_command:form.test_command||null,test_working_directory:form.test_working_directory||null,mcp_server_name:form.mcp_server_name.trim()||null};const r=await fetch(`${API}/api/tasks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){if(d.detail?.code==='dirty_worktree_confirmation_required')await loadBranches(form.project_path,true);throw Error(apiError(d.detail,'شروع تسک ناموفق بود'))}rememberTask(d)}catch(err){setNotice(err.message)}finally{setBusy(false)}}
  async function action(kind,body,retry=false){setBusy(true);setNotice(retry?'در حال اجرای git add . و تلاش مجدد برای commit…':'');try{const r=await fetch(`${API}/api/tasks/${task.id}/${kind}`,{method:'POST',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail,'انجام عملیات ناموفق بود'));rememberTask(d.task);if(kind==='commit')setCommitRetry(null);setNotice({commit:'تغییرات با موفقیت commit شدند.',push:'برنچ با موفقیت push شد.','merge-request':'درخواست ادغام با موفقیت ساخته شد.'}[kind])}catch(e){if(kind==='commit'){setCommitRetry({taskId:task.id,message:body?.message||task.commit_message||'',error:e.message});setNotice(retry?`تلاش مجدد برای commit هم ناموفق بود و نیاز به بازبینی انسانی دارد: ${e.message}`:`commit ناموفق بود. برای stage دوباره و تلاش مجدد، دکمهٔ «تلاش مجدد با git add .» را بزن.`)}else setNotice(e.message)}finally{setBusy(false)}}
  function retryCommit(){if(task)action('commit',{message:task.commit_message||commitRetry?.message||''},true)}
  async function runTestSetup(){if(!task)return;if(!window.confirm('دیتابیس تست محلی و قابل حذف است؟ این عملیات داده‌های آن را reset می‌کند.'))return;setBusy(true);setNotice('');try{const r=await fetch(`${API}/api/test-setup`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_path:task.project_path,confirm_test_database:true})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail,'اجرای setup تست ناموفق بود'));setTask(current=>({...current,test_setup_output:d.output}));setTab('test-setup');setNotice('Setup محیط تست با موفقیت انجام شد.')}catch(e){setNotice(e.message)}finally{setBusy(false)}}
  async function generateCommitMessage(){if(!task?.codex_thread_id)return;setBusy(true);setNotice('');try{const r=await fetch(`${API}/api/tasks/${task.id}/commit-message`,{method:'POST'});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail,'ساخت پیام commit ناموفق بود'));setTask(current=>({...current,commit_message:d.message}));setNotice(`پیام commit پیشنهادی ${agentLabelFor(task.agent_type)} در فیلد قرار گرفت.`)}catch(e){setNotice(e.message)}finally{setBusy(false)}}
  async function sendMessage(e){e.preventDefault();const message=chatMessage.trim();if(!message||!task?.codex_thread_id)return;setBusy(true);setNotice('');try{const r=await fetch(`${API}/api/tasks/${task.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail,'ارسال پیام ناموفق بود'));rememberTask(d);setChatMessage('');setTab('summary')}catch(err){setNotice(err.message)}finally{setBusy(false)}}
  async function addTodo(e){e.preventDefault();const content=todoDraft.trim();if(!content||!task)return;setBusy(true);setNotice('');try{const scheduled_for=todoScheduledFor?new Date(todoScheduledFor).toISOString():null;const r=await fetch(`${API}/api/tasks/${task.id}/todos`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content,...todoTarget,scheduled_for})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail,'ذخیره‌کردن Todo ناموفق بود'));rememberTask(d);setTodoDraft('');setTodoScheduledFor('')}catch(err){setNotice(err.message)}finally{setBusy(false)}}
